item.command:
/bin/zsh -c "cat > build.ts <<'EOF'
import { rm } from 'node:fs/promises';

await rm('dist', { recursive: true, force: true });
const result = await Bun.build({
  entrypoints: ['src/api.tsx', 'src/seed.ts'],
  outdir: 'dist',
  target: 'bun',
  env: 'disable',
  jsx: { development: false },
  external: ['react', 'react/jsx-runtime', 'react-dom/server'],
});
if ("'!result.success) throw new AggregateError(result.logs, '"'build failed');
EOF
cat > src/handlers.ts <<'EOF'
import { FindOrderQuery } from '@shop/orders';

export const handlers = new Map<Function, (query: { id: string }) => { orderId: string }>([
  [FindOrderQuery, (query: FindOrderQuery) => ({ orderId: query.id })],
]);
EOF
bun run typecheck && bun test && NODE_ENV=development bun run build && cat dist/seed.js && docker build -t shop-bun-migration ."

